package com.personal.meditation;
import static org.junit.Assert.*;import android.content.*;import android.os.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ServiceController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28)public class MeditationServiceTest{
 @Before public void reset(){MeditationService.busy=false;MeditationService.snapshot="{\"phase\":\"idle\"}";RuntimeEnvironment.getApplication().getSharedPreferences("meditation_settings",0).edit().clear().commit();}
 @Test public void foregroundTimerCanPauseResumeAndStopWithoutTheActivity()throws Exception{ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService s=controller.get();try{s.onStartCommand(new Intent().setAction(MeditationService.START),0,1);assertTrue(MeditationService.busy);assertEquals("preparing",new JSONObject(MeditationService.snapshot).getString("phase"));assertNotNull(Shadows.shadowOf(s).getLastForegroundNotification());s.onStartCommand(new Intent().setAction(MeditationService.PAUSE),0,2);assertEquals("paused",new JSONObject(MeditationService.snapshot).getString("phase"));s.onStartCommand(new Intent().setAction(MeditationService.RESUME),0,3);assertEquals("preparing",new JSONObject(MeditationService.snapshot).getString("phase"));s.onStartCommand(new Intent().setAction(MeditationService.STOP),0,4);assertFalse(MeditationService.busy);assertEquals("idle",new JSONObject(MeditationService.snapshot).getString("phase"));}finally{controller.destroy();}}
 @Test public void timeDisplayRoundsUp(){assertEquals("00:30",MeditationService.time(30000));assertEquals("00:30",MeditationService.time(29001));assertEquals("02:30",MeditationService.time(150000));assertEquals("00:00",MeditationService.time(0));}
 @Test public void liveStateReadsBetweenPublishedTicksWithoutQuantizingTheClock()throws Exception{ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService service=controller.get();try{long start=SystemClock.elapsedRealtime();service.onStartCommand(new Intent().setAction(MeditationService.START),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(1375,java.util.concurrent.TimeUnit.MILLISECONDS);long expected=30000-(SystemClock.elapsedRealtime()-start),live=new JSONObject(MeditationService.liveState()).getLong("remainingMs"),cached=new JSONObject(MeditationService.snapshot).getLong("remainingMs");assertEquals(expected,live);assertTrue(live<cached);service.onStartCommand(new Intent().setAction(MeditationService.PAUSE),0,2);long paused=new JSONObject(MeditationService.liveState()).getLong("remainingMs");Shadows.shadowOf(Looper.getMainLooper()).idleFor(2500,java.util.concurrent.TimeUnit.MILLISECONDS);assertEquals(paused,new JSONObject(MeditationService.liveState()).getLong("remainingMs"));service.onStartCommand(new Intent().setAction(MeditationService.STOP),0,3);}finally{controller.destroy();}}

 @Test public void completionPlaysEndingVibrationOnceAndCanStartAnotherSession()throws Exception{
  Context context=RuntimeEnvironment.getApplication();Settings settings=new Settings(context);JSONObject config=settings.get().put("minutes",8).put("intervals",6).put("bell","silent").put("quarter","silent");
  config.getJSONObject("vibrations").getJSONObject("end").put("enabled",true).put("ms",2300);assertTrue(settings.save(config.toString()));
  ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService service=controller.get();org.robolectric.shadows.ShadowVibrator vibration=Shadows.shadowOf((Vibrator)service.getSystemService(Context.VIBRATOR_SERVICE));vibration.setHasVibrator(true);
  try{service.onStartCommand(new Intent().setAction(MeditationService.START),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(510000,java.util.concurrent.TimeUnit.MILLISECONDS);
   assertFalse(MeditationService.busy);assertEquals("finished",new JSONObject(MeditationService.liveState()).getString("phase"));assertTrue(vibration.isVibrating());assertEquals(2300,vibration.getMilliseconds());
   Shadows.shadowOf(Looper.getMainLooper()).idleFor(2301,java.util.concurrent.TimeUnit.MILLISECONDS);assertFalse(vibration.isVibrating());
   service.onStartCommand(new Intent().setAction(MeditationService.START),0,2);assertTrue(MeditationService.busy);JSONObject next=new JSONObject(MeditationService.liveState());assertEquals("preparing",next.getString("phase"));assertEquals(480000,next.getLong("durationMs"));assertEquals(6,next.getInt("intervals"));
   Shadows.shadowOf(Looper.getMainLooper()).idleFor(3000,java.util.concurrent.TimeUnit.MILLISECONDS);assertTrue(MeditationService.busy);
  }finally{service.onStartCommand(new Intent().setAction(MeditationService.STOP),0,3);controller.destroy();}
 }

 @Test public void loopingBackgroundFollowsTheSessionWithoutBeingReplacedByBells()throws Exception{Context context=RuntimeEnvironment.getApplication();Settings settings=new Settings(context);assertTrue(settings.save(settings.get().put("minutes",1).put("countdownSeconds",0).put("intervals",6).put("ambient","brown_noise").toString()));org.robolectric.shadows.ShadowMediaPlayer.setMediaInfoProvider(source->new org.robolectric.shadows.ShadowMediaPlayer.MediaInfo(24000,0));ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService service=controller.get();try{service.onStartCommand(new Intent().setAction(MeditationService.START),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(1,java.util.concurrent.TimeUnit.MILLISECONDS);AmbientPlayer ambient=org.robolectric.util.ReflectionHelpers.getField(service,"ambient");android.media.MediaPlayer loop=ambient.playerForTests();assertNotNull(loop);assertTrue(loop.isPlaying());Shadows.shadowOf(Looper.getMainLooper()).idleFor(10000,java.util.concurrent.TimeUnit.MILLISECONDS);assertSame(loop,ambient.playerForTests());assertTrue(loop.isPlaying());service.onStartCommand(new Intent().setAction(MeditationService.PAUSE),0,2);assertFalse(loop.isPlaying());service.onStartCommand(new Intent().setAction(MeditationService.RESUME),0,3);assertTrue(loop.isPlaying());service.onStartCommand(new Intent().setAction(MeditationService.STOP),0,4);assertNull(ambient.playerForTests());}finally{service.onStartCommand(new Intent().setAction(MeditationService.STOP),0,5);controller.destroy();}}
}
